CREATE TABLE "User" (id TEXT PRIMARY KEY,username TEXT UNIQUE NOT NULL,name TEXT NOT NULL,password TEXT NOT NULL,role TEXT NOT NULL,active BOOLEAN NOT NULL DEFAULT true,"mustChange" BOOLEAN NOT NULL DEFAULT true,version INTEGER NOT NULL DEFAULT 1);
CREATE TABLE "Session" (token TEXT PRIMARY KEY,"userId" TEXT NOT NULL REFERENCES "User"(id) ON DELETE CASCADE,version INTEGER NOT NULL,expires TIMESTAMP(3) NOT NULL);
CREATE TABLE "Equipment" (id TEXT PRIMARY KEY,name TEXT NOT NULL,plant TEXT NOT NULL,department TEXT NOT NULL,area TEXT NOT NULL,line TEXT NOT NULL);
CREATE TABLE "Standard" (id TEXT PRIMARY KEY,family TEXT NOT NULL,revision INTEGER NOT NULL,title TEXT NOT NULL,"equipmentId" TEXT NOT NULL REFERENCES "Equipment"(id),target DOUBLE PRECISION NOT NULL,tolerance DOUBLE PRECISION NOT NULL,steps JSONB NOT NULL,created TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE(family,revision));
CREATE TABLE "Record" (id TEXT PRIMARY KEY,kind TEXT NOT NULL,"userId" TEXT NOT NULL REFERENCES "User"(id),"standardId" TEXT REFERENCES "Standard"(id),data JSONB NOT NULL,created TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX "Record_user_created" ON "Record"("userId",created);
CREATE TABLE "Content" (id TEXT PRIMARY KEY,kind TEXT NOT NULL,title TEXT NOT NULL,"equipmentId" TEXT REFERENCES "Equipment"(id),body TEXT NOT NULL,active BOOLEAN NOT NULL DEFAULT true);
CREATE TABLE "Policy" (role TEXT PRIMARY KEY,grants JSONB NOT NULL);
CREATE TABLE "Photo" (id TEXT PRIMARY KEY,"userId" TEXT NOT NULL REFERENCES "User"(id),created TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "Rate" (key TEXT PRIMARY KEY,count INTEGER NOT NULL,expires TIMESTAMP(3) NOT NULL);
